using namespace pas;using namespace pas::current_rails;using J=nlohmann::json;
J run(bool candidate,int offset,cost_family_v2::Control control){
 FakeClock clock;auto rt=std::make_unique<Runtime>(clock);const int n=control==cost_family_v2::Control::positive?648:81;int current_frame=0,last_body=0,last_tail=0;
 J frames=J::array(),events=J::array(),receipts=J::array();std::array<int,3> all{},measurement{};std::set<std::uint64_t> notes,intents;std::map<std::string,int> reasons;
 rt->event_output=[&](J event){const auto type=event.at("event").get<std::string>();if(type=="own_accepted_plan"){notes.insert(event.at("note").get<std::uint64_t>());intents.insert(event.at("intent").get<std::uint64_t>());}if(type!="current_observer_scene"&&type!="complete_raw_candidate_batch"&&type!="filtered_owner_scene"){event["dispatch_frame"]=current_frame;events.push_back(std::move(event));}};
 rt->receipt_output=[&](const auto&e){if(e.release){receipts.push_back({{"event","release"},{"frame",current_frame},{"requested",e.report.requested_ids},{"failed",e.report.failed_ids},{"unknown",e.report.unknown_ids}});return;}const int p=int(e.issued.phase);++all.at(p);if(current_frame>256)++measurement.at(p);receipts.push_back({{"event","injection"},{"dispatch_frame",current_frame},{"phase",p},{"intent",e.issued.intent_id},{"contact",e.issued.contact_id},{"source_frame",e.issued.source_frame_sequence},{"x",e.issued.x},{"y",e.issued.y},{"scheduled",e.issued.scheduled_ns},{"start",e.receipt.injection_start_ns},{"return",e.receipt.injection_return_ns},{"success",e.receipt.success},{"last_body_support_frame",last_body},{"last_tail_support_frame",last_tail}});};
 bool safe=true;int processed=0;for(int i=1;i<=n;++i){current_frame=i;Frame f;f.sequence=i;f.epoch=f.generation=f.geometry_version=1;f.width=1280;f.height=720;f.stride=3840;f.source_rotation=1;f.capture_complete_ns=f.pixels_ready_ns=1'000'000'000LL+i*20'000'000LL;f.rgb=cost_family_v2::image((i-1)%81,offset,control);clock.set(f.capture_complete_ns);bool ok=rt->dispatch(f,candidate);++processed;J support=J::array();for(size_t j=0;j<rt->last.count;++j){const auto&s=rt->last.support[j];reasons[std::string(s.reason)]++;if(s.accepted&&s.active&&s.body)last_body=i;if(s.accepted&&s.active&&s.tail)last_tail=i;support.push_back({{"note",s.note},{"active",s.active},{"accepted",s.accepted},{"body",s.body},{"tail",s.tail},{"terminal",s.terminal},{"reason",s.reason}});}J raw=J::array();for(const auto&c:rt->observer.candidate_batch().candidates)raw.push_back({{"kind",int(c.note.kind)},{"center",{c.note.center.x,c.note.center.y}},{"height",c.note.height},{"width",c.note.width},{"held_body",c.note.held_body_evidence},{"patch",c.note.held_body_patch},{"tail",c.note.tail?J::array({c.note.tail->x,c.note.tail->y}):J(nullptr)}});frames.push_back({{"frame",i},{"cycle",(i-1)/81},{"phase",(i-1)%81},{"generator_head",cost_family_v2::head((i-1)%81)},{"safe",ok},{"owned",rt->owner_processed},{"active",rt->backend.active_count()},{"down",rt->backend.downs},{"move",rt->backend.moves},{"up",rt->backend.ups},{"support",support},{"raw",raw}});if(!ok){safe=false;break;}}
 bool released=rt->finish();bool activity=measurement[0]>0&&measurement[2]>0;return {{"mode",candidate?"B":"A"},{"offset",offset},{"control",cost_family_v2::name(control)},{"requested",n},{"processed",processed},{"safe",safe},{"release_verified",released},{"ledger_valid",rt->ledger.valid()},{"ledger_reason",rt->ledger.reason()},{"active_final",rt->backend.active_count()},{"phase_counts",all},{"measurement_phase_counts",measurement},{"measurement_activity",activity},{"distinct_notes",notes},{"distinct_intents",intents},{"support_reasons",reasons},{"frames",frames},{"owner_events",events},{"receipts",receipts}};
}
int main(int argc,char**argv){try{if(argc!=2||std::filesystem::exists(argv[1]))throw std::runtime_error("fresh family report required");J runs=J::array();for(int offset:{-2,0,2})for(bool b:{false,true})runs.push_back(run(b,offset,cost_family_v2::Control::positive));for(auto c:{cost_family_v2::Control::absence,cost_family_v2::Control::effect,cost_family_v2::Control::no_tail_cap})for(bool b:{false,true})runs.push_back(run(b,0,c));J out={{"schema","pas.prelive-closed-tail-family.v2"},{"plan_sha256","57648e2ed1500930d382856362489ec43f8f26c717b5af01b3921e68fdd37b3a"},{"runs",runs},{"clock_domain","FakeClock_20ms_functional_only"},{"device_endpoints",0},{"physical_gold",0},{"cost_qualification",false}};std::ofstream f(argv[1]);f<<out.dump(2)<<'\n';if(!f)throw std::runtime_error("report write");return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
